const grid=document.querySelector('#lifeGrid'),search=document.querySelector('#lifeSearch'),count=document.querySelector('#recordCount'),empty=document.querySelector('#lifeEmpty'),filters=document.querySelector('#periodFilters'),dialog=document.querySelector('#recordDialog');let periodFilter='Todos';
const eraFor=p=>['Arcaico','Ediacárico'].some(x=>p.includes(x))?'Precámbrico':['Cámbrico','Ordovícico','Silúrico','Devónico','Carbonífero','Pérmico'].some(x=>p.includes(x))?'Paleozoico':['Triásico','Jurásico','Cretácico'].some(x=>p.includes(x))?'Mesozoico':'Cenozoico';
const periodId=p=>({Arcaico:'arcaico',Ediacárico:'ediacarico',Cámbrico:'cambrico',Ordovícico:'ordovicico',Silúrico:'silurico',Devónico:'devonico',Carbonífero:'carbonifero',Pérmico:'permico',Triásico:'triasico',Jurásico:'jurasico',Cretácico:'cretacico',Paleógeno:'paleogeno',Neógeno:'neogeno',Cuaternario:'cuaternario'})[p.split('–')[0]]||'';
function render(){const q=search.value.trim().toLocaleLowerCase('es');const records=LIFE_RECORDS.filter(r=>(periodFilter==='Todos'||eraFor(r.period)===periodFilter)&&`${r.name} ${r.period} ${r.group} ${r.habitat}`.toLocaleLowerCase('es').includes(q));count.textContent=`${records.length} DE ${LIFE_RECORDS.length} REGISTROS`;grid.innerHTML=records.map((r)=>`<button class="life-card" data-id="${r.id}"><span class="record-no">${String(LIFE_RECORDS.indexOf(r)+1).padStart(2,'0')}</span><span class="record-mark">${r.name.slice(0,2)}</span><span class="record-period">${r.period}</span><strong>${r.name}</strong><small>${r.group} · ${r.habitat}</small></button>`).join('');empty.hidden=records.length>0}
grid.addEventListener('click',e=>{const card=e.target.closest('.life-card');if(!card)return;const r=LIFE_RECORDS.find(x=>x.id===card.dataset.id);document.querySelector('#recordPeriod').textContent=r.period;document.querySelector('#recordName').textContent=r.name;document.querySelector('#recordMeta').innerHTML=`<span>${r.group}</span><span>${r.habitat}</span><span>${eraFor(r.period)}</span>`;document.querySelector('#recordSummary').textContent=r.summary;const link=document.querySelector('#recordTimeLink');link.href=`tiempo.html#${periodId(r.period)}`;dialog.showModal()});document.querySelector('#recordClose').addEventListener('click',()=>dialog.close());dialog.addEventListener('click',e=>{if(e.target===dialog)dialog.close()});search.addEventListener('input',render);filters.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;periodFilter=b.dataset.period;filters.querySelectorAll('button').forEach(x=>x.classList.toggle('active',x===b));render()});render();
